async function loadChatHistory(){
  try{
    if(!currentSessionId){ await loadChatSessions(); }
    const q = currentSessionId ? ('?sessionId='+encodeURIComponent(currentSessionId)) : '';
    const res = await fetch('/api/chat-history'+q);
    const data = await res.json();
    if(!data.ok) return;
    currentSessionId = data.sessionId || currentSessionId;
    renderSessionOptions(data.sessions||[]);
    renderVoiceHistory(data.history||[]);
  }catch(e){
    appendVoiceLine('assistant','Dạ em chưa tải được lịch sử chat, anh bấm tải lại trang giúp em ạ.');
  }
}

edits.newText:
async function loadChatHistory(){
  try{
    if(!currentSessionId){ await loadChatSessions(); }
    const q = currentSessionId ? ('?sessionId='+encodeURIComponent(currentSessionId)) : '';
    const res = await fetch('/api/chat-history'+q);
    const data = await res.json();
    if(!data.ok) return;
    currentSessionId = data.sessionId || currentSessionId;
    renderSessionOptions(data.sessions||[]);
    renderVoiceHistory(data.history||[]);
    const box=document.getElementById('voiceTranscript');
    if(box) box.style.display='block';
    const btn=document.getElementById('toggleHistoryBtn');
    if(btn) btn.textContent='Ẩn lịch sử';
  }catch(e){
    appendVoiceLine('assistant','Dạ em chưa tải được lịch sử chat, anh bấm tải lại trang giúp em ạ.');
  }
}

